"""Renders the output font's characters into small bitmap templates for reading stat sheets.

Run from the project root:  python scripts/generate-navine-glyphs.py
Writes src/core/navine-glyphs.ts. Needs Pillow.
"""
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

FONT = Path("public/fonts/NavineDemo-SemiCondensedItalic.ttf")
OUT = Path("src/core/navine-glyphs.ts")
CHARACTERS = "0123456789%"
GRID_WIDTH, GRID_HEIGHT = 20, 28

font = ImageFont.truetype(str(FONT), 240)
lines = [
    "// Generated by scripts/generate-navine-glyphs.py from the output font; do not edit.",
    "// Each glyph's ink, cropped to its bounding box and resampled to a "
    f"{GRID_WIDTH}x{GRID_HEIGHT} grid (\"#\" = ink).",
    "",
    "export interface GlyphTemplate {",
    "  /** Bounding-box width / height of the glyph. */",
    "  aspect: number;",
    "  rows: string[];",
    "}",
    "",
    f"export const GLYPH_GRID = {{ width: {GRID_WIDTH}, height: {GRID_HEIGHT} }};",
    "",
    "export const NAVINE_GLYPHS: Record<string, GlyphTemplate> = {",
]
for character in CHARACTERS:
    canvas = Image.new("L", (600, 400), 0)
    ImageDraw.Draw(canvas).text((100, 50), character, font=font, fill=255)
    box = canvas.getbbox()
    glyph = canvas.crop(box)
    grid = glyph.resize((GRID_WIDTH, GRID_HEIGHT), Image.LANCZOS)
    rows = []
    for y in range(GRID_HEIGHT):
        rows.append("".join("#" if grid.getpixel((x, y)) >= 128 else "." for x in range(GRID_WIDTH)))
    aspect = glyph.width / glyph.height
    lines.append(f'  "{character}": {{')
    lines.append(f"    aspect: {aspect:.4f},")
    lines.append("    rows: [")
    lines.extend(f'      "{row}",' for row in rows)
    lines.append("    ],")
    lines.append("  },")
lines.append("};")
OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
